import {assess,inScope,current,days} from './engine.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=v=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v||0);
const compact=v=>v>=1e6?(v/1e6).toFixed(1)+'m':v>=1000?(v/1000).toFixed(0)+'k':Math.round(v);
const pct=v=>(100*v).toFixed(1)+'%';
let config,result,sourceKey,sourceState,worker,running=false,progress='',error='',selected='portfolio',save;
const root=()=>document.querySelector('#economic-root');
const sourceFingerprint=s=>{const text=JSON.stringify([s.as_of,s.lines.map(l=>[l.id,l.supplier_id,l.po,l.item,l.schedule,l.required_date,l.open_qty,l.uom,l.deleted,l.finally_delivered,current(l)]),s.cases.map(c=>[c.id,c.closed])]);let hash=2166136261;for(const char of text){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619);}return (hash>>>0).toString(16);};
export function defaultEconomics(state){
  return {n:20000,seed:20260907,threshold:100000,mean_tolerance:500,common_probability:.15,common_days:5,as_of:state.as_of,source_key:sourceFingerprint(state),
    assumption_basis:'Synthetic, uncalibrated PoV inputs. Source exposure is a supplier-level approximation; independent downstream customer demand is assumed.',
    suppliers:state.suppliers.map((s,i)=>{
      const lines=state.lines.filter(l=>l.supplier_id===s.id&&inScope(l,state)),late=lines.filter(l=>assess(l,state).status==='Confirmed shortfall');
      const q=late.reduce((a,l)=>a+(assess(l,state).shortfall||0),0),knownDays=Math.max(0,...late.flatMap(l=>(current(l)?.legs||[]).map(x=>Math.max(0,days(x.date,l.required_date)))));
      return {id:s.id,name:s.name,enabled:late.length>0,source_lines:late.map(l=>l.po+'/'+l.item+'/'+l.schedule),source_status:late.length?'Confirmed shortfall':'No confirmed shortfall',source_shortfall:q,
        exposure_basis:'1 finished unit per component; pooled, disjoint downstream volume. Supplier representative delay is the largest stated lateness.',
        exposed_units:q||lines.reduce((a,l)=>a+l.open_qty,0),probability:late.length?1:.3,
        delay_low:Math.min(84,knownDays||2),delay_mode:Math.min(84,(knownDays||2)+3),delay_high:Math.min(84,(knownDays||2)+12),
        buffer_days:2,daily_demand:80+i*10,price:480+i*35,margin:145+i*12,cancel_low:.05,cancel_mode:.15,cancel_high:.4,
        penalty:.8,extra_cost_day:350,fixed_cost:2500,premium_unit:12,capacity_units:600,saved_days:5,lead_days:2,success:.8};
    })};
}
const field=(key,label,value,opts='min="0" step="any"',scope='global')=>`<label class="field"><span>${label}</span><input data-mc-field="${key}" data-scope="${scope}" type="number" value="${value}" ${opts} ${running?'disabled':''} required></label>`;
const ci=s=>`${euro(s.ci[0])} to ${euro(s.ci[1])}`;
function metric(label,value,note){return `<div class="metric"><div class="metric-top">${label}</div><div class="metric-number">${value}</div><div class="metric-note">${note}</div></div>`;}
function histogram(base,net){
  const max=Math.max(...base.counts,...net.counts,1),w=720,h=220,left=50,right=15,top=14,bottom=40,plotW=w-left-right,plotH=h-top-bottom,n=base.counts.length;
  return `<svg viewBox="0 0 ${w} ${h}" class="mc-plot" role="img" aria-label="Histogram of baseline and mitigated economic loss"><line x1="${left}" y1="${h-bottom}" x2="${w-right}" y2="${h-bottom}" stroke="#d2d2d2"/>${[0,.5,1].map(t=>`<line x1="${left}" y1="${top+plotH*(1-t)}" x2="${w-right}" y2="${top+plotH*(1-t)}" stroke="#ededed"/><text x="${left-8}" y="${top+plotH*(1-t)+4}" text-anchor="end" fill="#6F6F6F" font-size="11">${Math.round(max*t)}</text>`).join('')}${base.counts.map((count,i)=>`<rect x="${left+i*plotW/n}" y="${top+plotH*(1-count/max)}" width="${plotW/n-1}" height="${plotH*count/max}" fill="#c7c7c7"><title>${euro(base.edges[i])}–${euro(base.edges[i+1])}: ${count} baseline scenarios</title></rect><rect x="${left+i*plotW/n+plotW/n*.2}" y="${top+plotH*(1-net.counts[i]/max)}" width="${plotW/n*.55}" height="${plotH*net.counts[i]/max}" fill="#A01441"><title>${net.counts[i]} expediting scenarios in the same loss interval</title></rect>`).join('')}${[0,.25,.5,.75,1].map(t=>`<text x="${left+plotW*t}" y="${h-18}" text-anchor="middle" fill="#6F6F6F" font-size="12">€${compact(base.edges.at(-1)*t)}</text>`).join('')}<text x="${left}" y="${h-2}" fill="#6F6F6F" font-size="11">Economic loss per simulated 12-week exposure</text></svg>`;
}
function exceedance(base,net,threshold){const max=Math.max(base.cdf.at(-1).x,net.cdf.at(-1).x,threshold,1),width=720,height=200,left=50,plotW=655,plotH=150;const path=points=>points.map((p,i)=>`${i?'L':'M'}${left+plotW*p.x/max},${15+plotH*p.probability}`).join(' ');return `<svg class="mc-plot" viewBox="0 0 ${width} ${height}" role="img" aria-label="Exceedance curves: probability that economic loss exceeds a given value">${[0,.5,1].map(p=>`<line x1="50" x2="705" y1="${15+plotH*p}" y2="${15+plotH*p}" stroke="#ededed"/><text x="42" y="${19+plotH*p}" text-anchor="end" font-size="11" fill="#6F6F6F">${100*(1-p)}%</text>`).join('')}<path d="${path(base.cdf)}" fill="none" stroke="#868686" stroke-width="2"/><path d="${path(net.cdf)}" fill="none" stroke="#A01441" stroke-width="2"/><line x1="${left+plotW*threshold/max}" x2="${left+plotW*threshold/max}" y1="15" y2="165" stroke="#1d1d1d" stroke-dasharray="4 4"/>${[0,.5,1].map(t=>`<text x="${left+plotW*t}" y="185" text-anchor="middle" fill="#6F6F6F" font-size="12">€${compact(max*t)}</text>`).join('')}</svg>`;}
function resultsHtml(){if(!result)return `<section class="card empty"><h2>Run the model to quantify economic exposure</h2><p>Monte Carlo samples delays, cancellations, expediting success and a shared stress event.<br>Results include supplier-level loss distributions, portfolio tails and paired mitigation outcomes.</p></section>`;
  const s=selected==='portfolio'?result:result.suppliers.find(x=>x.id===selected)||result,b=s.baseline,m=s.mitigated;
  const rows=[...result.suppliers].sort((a,b)=>b.baseline.mean.mean-a.baseline.mean.mean);
  return `<div class="mc-results-title"><h2>Simulation results</h2><select aria-label="Result scope" data-mc-select="result"><option value="portfolio">All included suppliers</option>${result.suppliers.map(s=>`<option value="${s.id}" ${selected===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="metrics">${metric('Expected economic loss',euro(b.mean.mean),'95% mean CI: '+ci(b.mean))}${metric('P95 loss',euro(b.var),'95% of simulated outcomes are at or below this value')}${metric('Average worst 5% · ES95',euro(b.es),'Includes fractional probability at the tail boundary')}${metric('Probability above threshold',pct(b.exceedance.probability),`${euro(config.threshold)} · 95% CI ${pct(b.exceedance.ci[0])}–${pct(b.exceedance.ci[1])}`)}</div><div class="management-grid"><section class="card"><div class="card-head"><div><h2>Economic loss distribution</h2><p>Baseline and expediting use identical underlying disruptions.</p></div></div><div class="card-body"><div class="legend"><span><i class="swatch" style="background:#c7c7c7"></i>Without intervention</span><span><i class="swatch" style="background:#A01441"></i>With expediting, including cost</span></div>${histogram(s.distribution,s.mitigated_distribution)}<p class="inline-note">P5 ${euro(b.quantiles.p05)} · Median ${euro(b.quantiles.p50)} · P95 ${euro(b.quantiles.p95)}</p><p class="inline-note">Expected loss breakdown: lost contribution ${euro(s===result?rows.reduce((a,r)=>a+r.mean_lost_contribution,0):s.mean_lost_contribution)} · penalties ${euro(s===result?rows.reduce((a,r)=>a+r.mean_penalty,0):s.mean_penalty)} · extra costs ${euro(s===result?rows.reduce((a,r)=>a+r.mean_extra_cost,0):s.mean_extra_cost)}.</p><details><summary>Show exceedance curve (101 sampled quantiles)</summary>${exceedance(s.distribution,s.mitigated_distribution,config.threshold)}</details></div></section><section class="card"><div class="card-head"><div><h2>Is expediting worth its cost?</h2><p>Paired comparison; a negative saving means a higher expected loss.</p></div></div><div class="card-body"><div class="key-value"><span>Expected loss after expediting</span><strong>${euro(m.mean.mean)}</strong></div><div class="key-value"><span>P95 after expediting</span><strong>${euro(m.var)}</strong></div><div class="key-value"><span>Expected net saving</span><strong class="${s.net_saving.mean>=0?'green-text':'red-text'}">${euro(s.net_saving.mean)}</strong></div><div class="key-value"><span>95% CI for expected saving</span><span>${ci(s.net_saving)}</span></div>${s===result?`<div class="key-value"><span>Probability expediting is cheaper</span><strong>${pct(result.probability_mitigation_better.probability)}</strong></div>`:`<div class="key-value"><span>Expected intervention spend</span><strong>${euro(s.mean_expediting_cost)}</strong></div><div class="key-value"><span>Recoverable delayed revenue</span><strong>${euro(s.mean_delayed_revenue)}</strong></div>`}<p class="inline-note">Expediting pays a fixed fee when triggered, can fail, respects lead time and capacity, and adds a premium for recovered units. No intervention is assumed when stock fully covers the disruption.</p></div></section></div><section class="card" style="margin-top:22px"><div class="card-head"><div><h2>Economic impact by supplier</h2><p>Mean losses add up. Standalone P95 values do not. Tail contributions allocate the portfolio ES95.</p></div></div><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Supplier</th><th>Expected loss</th><th>Standalone P95</th><th>Portfolio tail contribution</th><th>Expediting cost</th><th>Net saving</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="text-button" data-mc-action="supplier-result" data-id="${r.id}">${esc(r.name)}</button></td><td>${euro(r.baseline.mean.mean)}<span class="cell-sub">Lost margin ${euro(r.mean_lost_contribution)}</span></td><td>${euro(r.baseline.var)}</td><td>${euro(r.tail_contribution)}</td><td>${euro(r.mean_expediting_cost)}</td><td class="${r.net_saving.mean>=0?'green-text':'red-text'}">${euro(r.net_saving.mean)}</td></tr>`).join('')}</tbody></table></div></section><div class="management-grid"><section class="card"><div class="card-head"><div><h2>Numerical precision</h2><p>Simulation error is separate from uncertainty in the assumptions.</p></div></div><div class="card-body"><div class="key-value"><span>Independent production scenarios</span><strong>${result.reproducibility.n.toLocaleString()}</strong></div><div class="key-value"><span>Portfolio mean: 95% CI half-width</span><strong>${euro(result.diagnostics.mean_half_width)}</strong></div><div class="key-value"><span>Mean tolerance ${euro(config.mean_tolerance)}</span><span class="badge ${result.diagnostics.mean_precision_met?'green':'amber'}">${result.diagnostics.mean_precision_met?'Met':'Increase runs'}</span></div><div class="key-value"><span>Tail bootstrap P95 interval</span><span>${euro(result.tail_diagnostic.var_ci[0])}–${euro(result.tail_diagnostic.var_ci[1])}</span></div><div class="key-value"><span>Tail bootstrap ES95 interval</span><span>${euro(result.tail_diagnostic.es_ci[0])}–${euro(result.tail_diagnostic.es_ci[1])}</span></div><p class="inline-note">An independent 1,000-run pilot suggests ${result.diagnostics.recommended_n_from_pilot.toLocaleString()} runs for mean tolerance and conservative ±1 percentage-point breach precision. Tail intervals use 100 bootstrap resamples and are diagnostic; atoms and sparse tails can make them misleading.</p>${[...result.baseline.warnings,...result.tail_diagnostic.warnings].map(x=>`<p class="inline-note amber-text">${esc(x)}</p>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2>Joint stress & model limits</h2><p>Shared disruption severity changes the portfolio tail.</p></div></div><div class="card-body"><div class="key-value"><span>Shared stress sampled</span><strong>${pct(result.diagnostics.realized_common_stress.probability)}</strong></div><div class="key-value"><span>Expected loss if shared stress is certain</span><strong>${euro(result.stress.mean_loss)}</strong></div><div class="key-value"><span>P95 if shared stress is certain</span><strong>${euro(result.stress.var)}</strong></div><details style="margin:18px 0"><summary>Sensitivity to uncalibrated assumptions</summary><p class="inline-note">One change at a time, using the same underlying scenarios. These are parameter stress cases, not confidence bounds.</p>${result.assumption_stress.map(x=>`<div class="key-value"><span>${esc(x.label)}</span><span>Mean ${euro(x.mean_loss)}<br>P95 ${euro(x.var)}</span></div>`).join('')}</details><details><summary>Assumptions, equations & reproducibility</summary><p class="inline-note">Uncovered days = max(0, delay − stock cover). Affected units = min(exposure, daily demand × uncovered days). Loss = affected units × cancellation fraction × contribution margin + unit-day penalties + incremental disruption costs. Recoverable delayed revenue is not added to loss.</p>${result.limitations.map(x=>`<p class="inline-note">${esc(x)}</p>`).join('')}<p class="mono">Seed ${result.reproducibility.seed} · ${result.reproducibility.bit_generator}<br>Python ${result.reproducibility.python} · NumPy ${result.reproducibility.numpy} · SciPy ${result.reproducibility.scipy}</p><p class="inline-note">Configuration ${result.reproducibility.config_sha256.slice(0,20)}…<br>Code ${result.reproducibility.code_sha256.slice(0,20)}…</p></details></div></section></div>`;
}
function paint(){if(!root())return;root().innerHTML=`<div class="page-head"><div><h1>Economic impact</h1><p>Monte Carlo simulation · 12-week supplier exposure · EUR</p></div><div class="head-actions"><button class="btn" data-mc-action="export-config">Export assumptions</button><button class="btn" data-mc-action="export-results" ${!result?'disabled':''}>Export results</button><button class="btn primary" data-mc-action="run" ${running?'disabled':''}>${running?'Simulation running…':'Run simulation'}</button></div></div><div class="notice"> <p><strong>Illustrative economic model.</strong> Confirmed shortages initialize exposed component quantities. The conversion to finished units, delay distributions and financial effects are editable assumptions—not calibrated supplier predictions. Downstream exposures are assumed to be disjoint.</p></div><form id="mc-form"><section class="card"><div class="card-head"><div><h2>Simulation controls</h2><p>One disruption episode per included supplier; costs are incremental to an on-time baseline.</p></div><button type="button" class="text-button" data-mc-action="reload" ${running?'disabled':''}>Reload current worklist exposure</button></div><div class="card-body mc-controls">${field('n','Production scenarios',config.n,'min="2000" max="100000" step="1000"')}${field('seed','Random seed',config.seed,'min="0" max="4294967295" step="1"')}${field('threshold','Loss threshold (€)',config.threshold)}${field('mean_tolerance','Mean precision target (€)',config.mean_tolerance,'min="1" step="1"')}${field('common_probability','Shared stress probability (0–1)',config.common_probability,'min="0" max="1" step="0.01"')}${field('common_days','Extra days in shared stress',config.common_days,'min="0" max="84" step="1"')}</div></section><section class="card"><div class="card-head"><div><h2>Supplier exposure & assumptions</h2><p>Confirmed-late suppliers start with occurrence probability 1. Other suppliers remain excluded until you choose to include them.</p></div></div><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Include</th><th>Supplier</th><th>Exposed finished units</th><th>Occurrence probability</th><th>Delay min / mode / max</th><th></th></tr></thead><tbody>${config.suppliers.map(s=>`<tr><td><input type="checkbox" data-mc-enabled="${s.id}" aria-label="Include ${esc(s.name)}" ${s.enabled?'checked':''} ${running?'disabled':''}></td><td><strong>${esc(s.name)}</strong><span class="cell-sub">${esc(s.source_status)} · ${s.source_shortfall} PC known gap</span></td><td>${s.exposed_units.toLocaleString()}</td><td>${pct(s.probability)}</td><td>${s.delay_low} / ${s.delay_mode} / ${s.delay_high} days</td><td><button class="text-button" type="button" data-mc-action="edit" data-id="${s.id}" ${running?'disabled':''}>Edit assumptions</button></td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>${config.suppliers.filter(s=>s.enabled).length} suppliers included · Worklist snapshot ${esc(config.as_of)}</span><button class="text-button" type="button" data-mc-action="save" ${running?'disabled':''}>Save assumptions with session</button></div></section></form>${running?`<div class="notice mc-progress" role="status"><p>${esc(progress)}</p><button class="btn compact" data-mc-action="cancel">Cancel</button></div>`:''}${error?`<div class="notice warning" role="alert"><p>${esc(error)}</p></div>`:''}<div id="mc-results" style="margin-top:24px">${resultsHtml()}</div>`;}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function editSupplier(id){const s=config.suppliers.find(s=>s.id===id),dialog=document.querySelector('#modal');const groups=[['Exposure & economics',[['exposed_units','Exposed finished units'],['probability','Occurrence probability (0–1)'],['daily_demand','Finished units needed per day'],['buffer_days','Stock cover (days)'],['price','Selling price / finished unit (€)'],['margin','Contribution margin / unit (€)'],['penalty','Penalty / affected unit / day (€)'],['extra_cost_day','Extra disruption cost / day (€)']]],['Conditional delay: triangular distribution',[['delay_low','Minimum late days'],['delay_mode','Most likely late days'],['delay_high','Maximum late days']]],['Conditional cancellation fraction: triangular distribution',[['cancel_low','Minimum fraction (0–1)'],['cancel_mode','Most likely fraction (0–1)'],['cancel_high','Maximum fraction (0–1)']]],['Expediting option',[['saved_days','Potential delay reduction (days)'],['lead_days','Earliest intervention arrival (days)'],['capacity_units','Maximum recoverable units'],['success','Success probability (0–1)'],['fixed_cost','Fee per triggered intervention (€)'],['premium_unit','Premium / recovered unit (€)']]]];document.querySelector('#modal-content').innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${esc(s.name)} · economic assumptions</h2><p>All economic inputs are synthetic. Stock and demand are in finished-product units.</p></div><button class="close" data-mc-action="close" aria-label="Close">×</button></div><form id="mc-supplier-form" data-id="${id}"><div class="modal-body"><p class="inline-note">Linked late PO lines: ${esc(s.source_lines.join(', ')||'None')}. ${esc(s.exposure_basis)}</p>${groups.map(([label,fields])=>`<h3 style="margin-top:24px">${label}</h3><div class="form-grid">${fields.map(([key,label])=>field(key,label,s[key],`min="${key==='daily_demand'?'.01':'0'}" ${['probability','cancel_low','cancel_mode','cancel_high','success'].includes(key)?'max="1"':''} step="any"`,'supplier')).join('')}</div>`).join('')}<p class="inline-note">Min/mode/max are elicited bounds, not P5/P50/P95. Extra disruption costs must exclude fixed costs already in the baseline. No mitigation budget is assumed; its spend is shown in the comparison.</p></div><div class="modal-foot"><button type="button" class="btn" data-mc-action="close">Cancel</button><button type="submit" class="btn primary">Apply assumptions</button></div></form>`;dialog.showModal();}
let localBackend=false,abortController,generation=0;
async function simulate(){if(running)return;if(sourceFingerprint(sourceState)!==sourceKey){error='Reload the current worklist exposure before simulating changed supplier evidence.';paint();return;}const form=document.querySelector('#mc-form');if(!form.reportValidity())return;if(!config.suppliers.some(s=>s.enabled)){error='Include at least one supplier.';paint();return;}running=true;error='';result=null;progress=localBackend?'Running the Python model…':'Preparing the Python simulation runtime…';paint();const submitted=structuredClone(config),token=++generation;
  try{if(localBackend){abortController=new AbortController();const response=await fetch('/api/simulate',{method:'POST',headers:{'Content-Type':'application/json','X-Assurance-Client':'native-ui'},body:JSON.stringify(submitted),signal:abortController.signal});const data=await response.json();if(!response.ok)throw Error(data.error||'Simulation failed.');if(token!==generation)return;if(sourceFingerprint(sourceState)!==submitted.source_key)throw Error('Supplier evidence changed during the run. Reload exposure and run again.');result=data;running=false;paint();}
  else {worker ||=new Worker('./mc-worker.js');worker.onmessage=({data})=>{if(token!==generation)return;if(data.type==='progress'){progress=data.message;paint();}else if(data.type==='result'){if(sourceFingerprint(sourceState)!==submitted.source_key){result=null;error='Supplier evidence changed during the run. Reload exposure and run again.';}else result=data.result;running=false;paint();}else{error=data.message;running=false;paint();}};worker.onerror=e=>{error='Python runtime could not load. Check network access to cdn.jsdelivr.net, or run the downloadable Python app. '+e.message;running=false;worker.terminate();worker=null;paint();};worker.postMessage(submitted);}}
  catch(e){if(token!==generation)return;running=false;error=e.name==='AbortError'?'Simulation canceled.':e.message;paint();}}
export function mountEconomics(state,backend,onSave){if(sourceState&&sourceState!==state){config=null;result=null;error='';}sourceState=state;localBackend=backend;save=onSave;const key=sourceFingerprint(state);if(!config){config=defaultEconomics(state);if(state.economics&&Array.isArray(state.economics.suppliers)){for(const k of Object.keys(config))if(typeof config[k]==='number'&&Number.isFinite(state.economics[k]))config[k]=state.economics[k];for(const s of config.suppliers){const old=state.economics.suppliers.find(r=>r.id===s.id);if(old){for(const k of Object.keys(s))if(typeof s[k]==='number'&&Number.isFinite(old[k]))s[k]=old[k];if(typeof old.enabled==='boolean')s.enabled=old.enabled;}}}sourceKey=typeof state.economics?.source_key==='string'?state.economics.source_key:key;config.source_key=sourceKey;}if(key!==sourceKey){result=null;error='The supplier evidence or snapshot changed. Reload current worklist exposure to refresh the model inputs; custom assumptions are retained until then.';}paint();}
document.addEventListener('change',event=>{const e=event.target;if(e.dataset.mcField&&e.dataset.scope==='global'){config[e.dataset.mcField]=Number(e.value);result=null;error='';const area=document.querySelector('#mc-results');if(area)area.innerHTML=resultsHtml();const exportButton=document.querySelector('[data-mc-action=export-results]');if(exportButton)exportButton.disabled=true;}if(e.dataset.mcEnabled){config.suppliers.find(s=>s.id===e.dataset.mcEnabled).enabled=e.checked;result=null;paint();}if(e.dataset.mcSelect==='result'){selected=e.value;paint();}});
document.addEventListener('click',async event=>{const e=event.target.closest('[data-mc-action]');if(!e||e.disabled)return;event.preventDefault();const action=e.dataset.mcAction;if(action==='run')return simulate();if(action==='edit')return editSupplier(e.dataset.id);if(action==='close')return document.querySelector('#modal').close();if(action==='supplier-result'){selected=e.dataset.id;paint();return;}if(action==='reload'){config=defaultEconomics(sourceState);sourceKey=sourceFingerprint(sourceState);result=null;error='';paint();return;}if(action==='save'){await save(structuredClone(config));return;}if(action==='cancel'){generation++;worker?.terminate();worker=null;abortController?.abort();running=false;progress='';error='Simulation canceled. A running local calculation may finish on the server; its output will not be applied.';paint();return;}if(action==='export-config')download('economic-assumptions.json',config);if(action==='export-results'&&result)download('economic-simulation-results.json',result);});
document.addEventListener('submit',event=>{if(event.target.id!=='mc-supplier-form')return;event.preventDefault();const f=event.target;if(!f.reportValidity())return;const updated={...config.suppliers.find(s=>s.id===f.dataset.id)};for(const e of f.querySelectorAll('[data-mc-field]'))updated[e.dataset.mcField]=Number(e.value);for(const prefix of ['delay','cancel'])if(!(updated[prefix+'_low']<=updated[prefix+'_mode']&&updated[prefix+'_mode']<=updated[prefix+'_high'])){showFormError(f,'Minimum must be no greater than mode, and mode no greater than maximum.');return;}if(updated.margin>updated.price){showFormError(f,'Contribution margin cannot exceed selling price.');return;}Object.assign(config.suppliers.find(s=>s.id===f.dataset.id),updated);result=null;document.querySelector('#modal').close();paint();});

function showFormError(form,message){let el=form.querySelector('.error');if(!el){el=document.createElement('p');el.className='error';el.setAttribute('role','alert');form.querySelector('.modal-body').prepend(el);}el.textContent=message;}
